class Solution {
public:
    vector<vector<long long>> splitPainting(vector<vector<int>>& segments) {
        map<long long, long long> diff;
        for (auto& s : segments) {
            diff[s[0]] += s[2];
            diff[s[1]] -= s[2];
        }
        vector<vector<long long>> ans;
        long long currColor = 0, prev = 0;
        for (auto& [pt, delta] : diff) {
            if (currColor > 0 && pt > prev) {
                ans.push_back({prev, pt, currColor});
            }
            currColor += delta;
            prev = pt;
        }
        return ans;
    }
};

class Solution {
    public java.util.List<java.util.List<Long>> splitPainting(int[][] segments) {
        java.util.TreeMap<Long, Long> diff = new java.util.TreeMap<>();
        for (int[] s : segments) {
            long start = s[0], end = s[1], color = s[2];
            diff.put(start, diff.getOrDefault(start, 0L) + color);
            diff.put(end, diff.getOrDefault(end, 0L) - color);
        }
        java.util.List<java.util.List<Long>> ans = new java.util.ArrayList<>();
        long currColor = 0, prev = 0;
        for (java.util.Map.Entry<Long, Long> entry : diff.entrySet()) {
            long pt = entry.getKey(), delta = entry.getValue();
            if (currColor > 0 && pt > prev) {
                ans.add(java.util.Arrays.asList(prev, pt, currColor));
            }
            currColor += delta;
            prev = pt;
        }
        return ans;
    }
}

var splitPainting = function(segments) {
  const diff = new Map();
  for (const [start, end, color] of segments) {
    diff.set(start, (diff.get(start) || 0) + color);
    diff.set(end, (diff.get(end) || 0) - color);
  }
  const sortedPts = Array.from(diff.keys()).sort((a, b) => a - b);
  const ans = [];
  let currColor = 0, prev = sortedPts[0];
  for (const pt of sortedPts) {
    if (currColor > 0 && pt > prev) {
      ans.push([prev, pt, currColor]);
    }
    currColor += diff.get(pt);
    prev = pt;
  }
  return ans;
};
